package com.nexus.agent.security

import javax.crypto.AEADBadTagException
import javax.crypto.Cipher
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * AES-256-GCM with a 128-bit authentication tag. On encrypt the IV is generated by the
 * Cipher itself (never caller-supplied), which is required by Android Keystore keys that
 * mandate randomized encryption; the IV is read back via [Cipher.getIV] and stored in the
 * versioned format. On decrypt the stored IV is supplied back. Pure JCE, so the same code
 * runs on Android and the JVM (which is what makes the round-trip/tamper unit tests work).
 */
class AesGcmCipher {
    fun encrypt(plaintext: ByteArray, key: SecretKey): ByteArray {
        val cipher = Cipher.getInstance(TRANSFORMATION)
        cipher.init(Cipher.ENCRYPT_MODE, key)
        val iv = cipher.iv ?: throw CryptoException("provider did not generate an IV")
        return CiphertextFormat.encode(iv, cipher.doFinal(plaintext))
    }

    fun decrypt(encoded: ByteArray, key: SecretKey): ByteArray {
        val parsed = CiphertextFormat.parse(encoded)
        val cipher = Cipher.getInstance(TRANSFORMATION)
        return try {
            cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(TAG_BITS, parsed.iv))
            cipher.doFinal(parsed.ciphertextAndTag)
        } catch (e: AEADBadTagException) {
            throw TamperDetectedException(
                "GCM authentication failed: ciphertext was tampered with or the key is wrong",
                e
            )
        }
    }

    companion object {
        private const val TRANSFORMATION = "AES/GCM/NoPadding"
        private const val TAG_BITS = 128
    }
}
